function validate([blocks, split]) {
  if (!Array.isArray(blocks) || blocks.length < 1 || blocks.length > 1000) return 'blocks needs 1 to 1000 values.';
  if (blocks.some(t => !Number.isInteger(t) || t < 1 || t > 100000)) return 'Each block time is a whole number from 1 to 100000.';
  if (!Number.isInteger(split) || split < 1 || split > 100) return 'split is a whole number from 1 to 100.';
  return null;
}

