function minBuildTime(blocks, split) {
  const n = blocks.length;
  if (n <= 12) {
    // Try every way to divide each worker's set of blocks between the two workers it splits into.
    const memo = new Map();
    const best = (mask) => {
      if ((mask & (mask - 1)) === 0) return blocks[31 - Math.clz32(mask)];
      if (memo.has(mask)) return memo.get(mask);
      const low = mask & -mask;
      let result = Infinity;
      for (let part = (mask - 1) & mask; part > 0; part = (part - 1) & mask) {
        if ((part & low) === 0) continue;
        result = Math.min(result, split + Math.max(best(part), best(mask ^ part)));
      }
      memo.set(mask, result);
      return result;
    };
    return best((1 << n) - 1);
  }
  // Larger inputs: binary search the finishing time, checking each candidate level by level.
  const sorted = [...blocks].sort((a, b) => b - a);
  const feasible = (limit) => {
    let workers = 1, elapsed = 0, i = 0;
    while (i < n) {
      if (sorted[i] + elapsed > limit) return false;
      if (workers >= n - i) return true;
      let urgent = 0;
      while (i + urgent < n && sorted[i + urgent] + elapsed + split > limit) urgent++;
      if (urgent >= workers) return false;
      i += urgent;
      workers = Math.min(n, 2 * (workers - urgent));
      elapsed += split;
    }
    return true;
  };
  let low = sorted[0], high = sorted[0] + split * n;
  while (low < high) {
    const mid = Math.floor((low + high) / 2);
    if (feasible(mid)) high = mid; else low = mid + 1;
  }
  return low;
}

