    const n = 900 + Math.floor(rand() * 101);
    const top = rand() < 0.5 ? 100000 : 1 + Math.floor(rand() * 500);
    return [Array.from({ length: n }, () => 1 + Math.floor(rand() * top)), 1 + Math.floor(rand() * 100)];
  }
  const n = 1 + Math.floor(rand() * 8);
  const top = rand() < 0.5 ? 5 : 40;
